function validateChanges(event) {
	var errorMessages = [];

	// events that require a player
	var playerRequired = [];
	var eventType = $('#liveGameEventType').val()

	// no event type text
	if(eventType == '') {
		$('#liveGameEventType_chzn a').effect("highlight", {color:"#FF0000"}, 2000);
		errorMessages.push('EventType muss ausgewählt werden');
		event.preventDefault();
	}

	if(eventType != '' && jQuery.inArray(parseInt(eventType), playerRequired) > -1) {
		if ($("#eventPlayer1").val() == 0) {
			$('#eventPlayer1').next().effect("highlight", {color:"#FF0000"}, 2000);
			errorMessages.push('Spieler muss ausgewählt werden');
			event.preventDefault();
		}
	}

	// check if team and selected player match
	if ($("#eventPlayer1").val() != 0) {
		var selectedTeamId = $("[name=eventTeam]:checked").val();
		var selectedPlayerTeamId = $("#eventPlayer1 option:selected").parent().attr("id");

		if (selectedTeamId != selectedPlayerTeamId) {
			$('.eventTeam').effect("highlight", {color:"#FF0000"}, 2000);
			$('#eventPlayer1').next().effect("highlight", {color:"#FF0000"}, 2000);
			errorMessages.push('Spieler und Team stimmen nicht überein');
			event.preventDefault();
		}
	}

	// events that require a team
	var teamRequired = [EVENT_TYPE_GOAL, EVENT_TYPE_CORNER, EVENT_TYPE_FOUL, EVENT_TYPE_FREE_KICK, EVENT_TYPE_PENALTY,
		EVENT_TYPE_YELLOW_CARD, EVENT_TYPE_RED_CARD, EVENT_TYPE_GOAL_SELF];

	if(eventType != '' && jQuery.inArray(parseInt(eventType), teamRequired) > -1 && $("#LivegameEventTeamGeneral:checked").val() == 0) {
		$('.eventTeam').effect("highlight", {color:"#FF0000"}, 2000);
		errorMessages.push('Team muss ausgewählt werden');
		event.preventDefault();
	}

	// no event without minute
	if($('#liveGameEventMinute').val() == '') {
		$('#liveGameEventMinute').effect("highlight", {color:"#FF0000"}, 2000);
		errorMessages.push('Minute muss eingegeben werden');
		event.preventDefault();
	}
	// no event without text
	if($('#eventText').val().trim() == '') {
		$('#eventText').effect("highlight", {color:"#FF0000"}, 2000);
		errorMessages.push('Text muss eingegeben werden');
		event.preventDefault();
	}

	// no text longer than 1024 chars
	if($('#eventText').val().length > 1024) {
		$('#eventText').effect("highlight", {color:"#FF0000"}, 2000);
		errorMessages.push('Der Kommentar enthält mehr als 1024 Zeichen, bitte kürzen.');
		event.preventDefault();
	}

	// events that requiere an active game
	var activeGameRequired = ['7', '8', '9', '10', '11', '12', '13', '14', '17', '29'];
	if(jQuery.inArray($('#liveGameEventType').val(), activeGameRequired) > -1 && gameData.gameState == GAME_STATE_NOT_STARTED) {
		$(".gameStatus").effect("highlight", {color:"#FF0000"}, 2000);
		errorMessages.push('Nur bei einem aktiven Spiel möglich');
		event.preventDefault();
	}

	if (gameData.gameState == GAME_STATE_VERIFIED && typeof canEditAfterVerification === 'undefined') {
		$(".gameStatus").effect("highlight", {color:"#FF0000"}, 2000);
		errorMessages.push('Spiel wurde bereits verifiziert und kann nicht mehr verändert werden');
		event.preventDefault();
	}


	if (errorMessages.length > 0) {
		var errorMessageHTML = '<ul>';
		$.each(errorMessages, function() {
			errorMessageHTML += ('<li>' + this + '</li>');
		});
		errorMessageHTML += '</ul>'
		$('div.eventErrors').html(errorMessageHTML).show();
	}
}

function setDefaultText() {
	var defaultText;
	var eventType = $("#liveGameEventType").val()

	if (eventType) {
		switch (parseInt($("#liveGameEventType").val())) {
			case EVENT_TYPE_GOAL:
				var selectedTeam = $("input[type='radio'][name='eventTeam']:checked")[0]
				if (selectedTeam && selectedTeam.value != "0") {
					defaultText = "Tor, Toor, Tooor für " + $("input[type='radio'][name='eventTeam']:checked").next().text() + ' zum '
					if (selectedTeam.id == 'LivegameEventTeamHome') {
						defaultText += (gameData.scoreHome + 1) + ':' + gameData.scoreAway
					} else {
						defaultText += gameData.scoreHome + ':' + (gameData.scoreAway + 1)
					}
					if ($('#eventPlayer1').val() != '') {
						defaultText += ', Torschütze: ' + $('#eventPlayer1 option:selected').data('name') + '.'
					}
				}
				break;
			case EVENT_TYPE_GOAL_SELF:
				var selectedTeam = $("input[type='radio'][name='eventTeam']:checked")[0]
				if (selectedTeam && selectedTeam.value != "0") {
					defaultText = "Eigentor durch " + $("input[type='radio'][name='eventTeam']:checked").next().text() + ', neuer Spielstand: '
					if (selectedTeam.id == 'LivegameEventTeamAway') {
						defaultText += (gameData.scoreHome + 1) + ':' + gameData.scoreAway
					} else {
						defaultText += gameData.scoreHome + ':' + (gameData.scoreAway + 1)
					}
					defaultText += "!"
					if ($('#eventPlayer1').val() != '') {
						defaultText += ' Unglücklicher Torschütze ist ' + $('#eventPlayer1 option:selected').data('name') + '.'
					}
				}
				break;
			case EVENT_TYPE_SUBSTITUTE:
				var selectedTeam = $("input[type='radio'][name='eventTeam']:checked")[0]
				if (selectedTeam && selectedTeam.value != "0") {
					defaultText = "Wechsel bei " + $("input[type='radio'][name='eventTeam']:checked").next().text() + '.'
					if ($('#eventPlayer1').val() != '') {
						defaultText += ' Aus dem Spiel: ' + $('#eventPlayer1 option:selected').data('name') + '.'
					}
					if ($('#eventPlayer2').val() != '') {
						defaultText += ' Neu im Spiel: ' + $('#eventPlayer2 option:selected').data('name') + '.'
					}
				}
				break;
			case EVENT_TYPE_YELLOW_CARD:
				defaultText = composeCardDefaultText("Gelbe Karte")
				break;
			case EVENT_TYPE_YELLOW_RED_CARD:
				defaultText = composeCardDefaultText("Gelb/Rote Karte")
				break;
			case EVENT_TYPE_RED_CARD:
				defaultText = composeCardDefaultText("Rote Karte")
				break;
			case EVENT_TYPE_BLUE_CARD:
				defaultText = composeCardDefaultText("Blaue Karte")
				break;
		}
	}

	if(defaultText && (preventEventText == false || $('#eventText').val() == '')) {
		$('#eventText').val(defaultText)
		preventEventText = false;
	}
}

function startGameTimer() {

	var startTime = new Date(Date.parse(gameData.startTime));
	if(gameData.kickOffTimeOvertime2) {
		startTime = new Date(Date.parse(gameData.kickOffTimeOvertime2));
		startTime = new Date(startTime.getTime() - 120*60000)
	} else if(gameData.kickOffTimeOvertime) {
		startTime = new Date(Date.parse(gameData.kickOffTimeOvertime));
		startTime = new Date(startTime.getTime() - 105*60000)
	} else if(gameData.kickOffTimeHalftime2) {
		startTime = new Date(Date.parse(gameData.kickOffTimeHalftime2));
		startTime = new Date(startTime.getTime() - 60*60000)
	} else if(gameData.kickOffTime) {
		startTime = new Date(Date.parse(gameData.kickOffTime));
	}

    var ua = navigator.userAgent.toLowerCase();
    if (navigator.userAgent.indexOf('Safari') != -1 && navigator.userAgent.indexOf('Chrome') == -1) {
		var dateSplit = gameData.startTime.split(/[^0-9]/);
		startTime = new Date (dateSplit[0],dateSplit[1]-1,dateSplit[2],dateSplit[3],dateSplit[4]);
	}
	var currentTime = new Date();
	var gameDuration = gameData.duration * 60;
	var elapsedTime = (startTime - currentTime) / 1000;
	var timerCorrection = 0;
	var timerCookie = Cookies.get('lp-timer-correction-' + gameData.id);

	if(timerCookie) {
        $('#timer-correction-mins').val(timerCookie);
	}
	if($('#timer-correction-mins').length) {
		timerCorrection = $('#timer-correction-mins').val() * 60;
	}
    elapsedTime = elapsedTime - timerCorrection;
	$('#timer').countdown('destroy');
	if(gameData.gameState >= GAME_STATE_SECOND_HALF) {
		if(-(gameDuration*60/2) > elapsedTime && elapsedTime > -(gameDuration*60/2)+900) {
			$("#timer").html("<span class=\"minutes\">" + gameDuration/2/60 + "</span>m <span>00</span>s");
		} else {
			$("#timer").countdown({since: elapsedTime + 900, format: 'MS', layout: '<span class=\"minutes\">{mn}</span>m <span>{sn}</span>s'/*, onTick: setEventMinute*/});
		}
	} else if(gameData.gameState == GAME_STATE_HALFTIME) {
        $("#timer").html("<span class=\"minutes\">" + gameDuration/2/60 + "</span>m <span>00</span>s");
	} else if(gameData.gameState == GAME_STATE_GAME_STARTED) {
		$("#timer").countdown({since: elapsedTime, format: 'MS', layout: '<span class=\"minutes\">{mn}</span>m <span>{sn}</span>s' /*, onTick: setEventMinute*/});
	}
}

