function composeCardDefaultText(cardType) {
	var selectedTeam = $("input[type='radio'][name='eventTeam']:checked")[0]
	defaultText = cardType
	if ($('#eventPlayer1').val() != '') {
		defaultText += ' für ' + $('#eventPlayer1 option:selected').data('name')
	}
	if (selectedTeam && selectedTeam.value != "0") {
		defaultText += " (" + $("input[type='radio'][name='eventTeam']:checked").next().text() + ').'
	}
	return defaultText
}

function zebraEventsTable() {
	$(".list tr.event.odd").removeClass("odd");
	$(".list tr.event").not(".hidden").each(function(index) {
		if(index % 2 != 0) {
			$(this).addClass("odd");
		}
	});
}

function showHiddenEvents() {
	$(".list tr.event.hidden").removeClass('hidden');
	zebraEventsTable();
}

function increaseTimerCorrection() {
	var currentValue = $('#timer-correction-mins').val();
	currentValue++;
    $('#timer-correction-mins').val(currentValue);
    $('#timer-correction-mins').trigger("change");
}

function decreaseTimerCorrection() {
    var currentValue = $('#timer-correction-mins').val();
    currentValue--;
    $('#timer-correction-mins').val(currentValue);
    $('#timer-correction-mins').trigger("change");
}

